// Avok Interactive mark, embedded as a data URI so the plain-JS
// frontend needs no asset pipeline. Generated from the canonical
// brand mark (brand/avok-mark.png, center-cropped 4% to clear the
// source art's white corner artifacts) at 256x256, PNG.
// Regenerate when the brand mark changes; do not edit by hand.
window.AVOK_MARK_DATA_URI = "data:image/png;base64,";
document.querySelectorAll("img.brand-logo").forEach(function (img) {
  img.src = window.AVOK_MARK_DATA_URI;
});
